function matchesCourse(c){
  const text=`${c.name} ${c.region} ${c.city} ${c.address||''} ${typeLabel(c)}`.toLocaleLowerCase('ko');
  if(region!=='전체' && c.region!==region) return false;
  if(city && c.city!==city) return false;
  if(operationFilter!=='all' && c.operationType!==operationFilter) return false;
  if(holesFilter!=='all' && (holesFilter==='36plus'?Number(c.holes)<36:Number(c.holes)!==Number(holesFilter))) return false;
  if(availabilityFilter==='bookable' && !c.bookable) return false;
  if(query && !text.replace(/\s/g,'').includes(query.toLocaleLowerCase('ko').replace(/\s/g,''))) return false;
  if(filters.includes('2\uc778 \uac00\ub2a5') && !c.bookable) return false;
  if(filters.includes('\ub178\uce90\ub514') && !c.noCaddie) return false;
  if(filters.includes('\ud2b9\uac00') && !timesFor(c).some(item=>item.specialOffer)) return false;
  if(filters.includes('18\ud640') && c.holes!==18) return false;
  return true;
}
function list(){
  let results=courses.filter(matchesCourse);
  if(sort==='price') results=results.slice().sort((a,b)=>(a.price??999999999)-(b.price??999999999));
  if(sort==='time') results=results.slice().sort((a,b)=>(a.times?.[0]?.time||'99:99').localeCompare(b.times?.[0]?.time||'99:99'));
  const visible=results.slice(0,visibleCount);
  const filterNames=['2\uc778 \uac00\ub2a5','\ub178\uce90\ub514','18\ud640','\ud2b9\uac00','\uc624\ub298 \uc608\uc57d','\uc8fc\ub9d0'];
  return `<div class="result-top"><button class="back" data-go="home">\u2039</button><h1>\uac80\uc0c9 \uacb0\uacfc</h1><button class="condition-edit" data-sheet>\uc870\uac74 \ubcc0\uacbd</button></div><button class="search-summary fixed-condition" data-sheet>${region}${city?' · '+city:''} \u00b7 ${currentDateShort()} \u00b7 ${people}\uba85 <b>\uc870\uac74 \ubcc0\uacbd</b></button>
  <div class="chips region-filters">${regionOptions.map(item=>`<button class="chip ${region===item.code?'active':''}" data-region-filter="${item.code}">${item.label}</button>`).join('')}</div>
  <div class="result-filters national-filters"><label>시·군<select id="result-city"><option value="">전체 시·군</option>${citiesFor(region).map(value=>`<option value="${value}" ${city===value?'selected':''}>${value}</option>`).join('')}</select></label><label>운영형태<select id="operation-filter"><option value="all">전체</option><option value="public" ${operationFilter==='public'?'selected':''}>대중제</option><option value="membership" ${operationFilter==='membership'?'selected':''}>회원제</option><option value="mixed" ${operationFilter==='mixed'?'selected':''}>혼합형</option></select></label><label>홀 수<select id="holes-filter"><option value="all">전체</option><option value="9" ${holesFilter==='9'?'selected':''}>9홀</option><option value="18" ${holesFilter==='18'?'selected':''}>18홀</option><option value="27" ${holesFilter==='27'?'selected':''}>27홀</option><option value="36plus" ${holesFilter==='36plus'?'selected':''}>36홀 이상</option></select></label><label>조회 범위<select id="availability-filter"><option value="all">전체 골프장</option><option value="bookable" ${availabilityFilter==='bookable'?'selected':''}>시연 예약 가능</option></select></label></div>
  <div class="sort-row"><div class="chips">${[['recommend','\ucd94\ucc9c\uc21c'],['price','\ub0ae\uc740 \uac00\uaca9\uc21c'],['time','\ube60\ub978 \uc2dc\uac04\uc21c']].map(([id,label])=>`<button class="chip ${sort===id?'active':''}" data-sort="${id}">${label}</button>`).join('')}</div><button class="filter-reset" data-reset-search>\ucd08\uae30\ud654</button></div><div class="chips">${filterNames.map(name=>`<button class="chip ${filters.includes(name)?'active':''}" data-filter="${name}">${name}</button>`).join('')}</div><p class="result-count"><b>${results.length}</b>\uac1c \uace8\ud504\uc7a5</p>
  <section class="result-group"><h2>전국 골프장</h2><p>전국 모든 골프장에서 예약 흐름을 시험할 수 있습니다. ${demoNotice}</p><div class="course-list">${visible.map(listCard).join('')||'<div class="empty">검색 결과가 없습니다.<br>검색어 또는 필터를 변경해보세요.</div>'}</div>${visible.length<results.length?`<button class="load-more" data-load-more>더 보기 (${results.length-visible.length}곳)</button>`:''}</section>`;
}
function listCard(c){const saved=favorites().includes(c.id),items=timesFor(c),first=items.find(item=>item.specialOffer)||items[0];return `<article class="list-card"><div class="list-image">⛳</div><div class="list-info"><div class="card-title"><h3 data-course="${c.id}">${c.name}</h3><button class="heart ${saved?'saved':''}" data-favorite="${c.id}" aria-label="찜하기">${saved?'♥':'♡'}</button></div><p>${c.region} · ${c.city} · ${holeLabel(c)} · ${typeLabel(c)}</p><div class="list-price">${first?.specialOffer?`<strong><s>${won(first.regularPrice)}</s> ${won(first.price)} / 1인</strong><span class="special-badge">특가 ${first.specialOffer.discountRate}%</span>`:`<strong>${won(first?.price)} / 1인</strong><span>시연 가격</span>`}</div><p class="demo-slot">${currentDateShort()} · ${first?.time||'티타임 확인 필요'} · 잔여 ${first?.remaining??0}팀</p><small class="demo-warning">${demoNotice}</small><div class="card-actions"><button class="outline" data-course="${c.id}">상세보기</button><button data-reserve-course="${c.id}">시연 예약</button></div></div></article>`}

function detail(){
  const saved=favorites().includes(course.id);
  const displayTimes=timesFor(course);
  const rates=ratesFor(course);
  const courseNames=course.courses?.length?course.courses.map(name=>`${name} 코스`).join(' · '):'코스 정보 확인 중';
  const actualGreen=course.verifiedGreenFee==null?'가격 확인 필요':won(course.verifiedGreenFee);
  if(!course.bookable)return `<div class="detail-top"><button class="back" data-go="list">‹</button><div class="detail-course-title"><h1>${course.name}</h1><button class="heart compact-favorite ${saved?'saved':''}" data-favorite="${course.id}" aria-label="찜하기">${saved?'♥':'♡'}</button></div><div class="detail-actions"><button data-share aria-label="공유하기">↧</button></div></div>
  <div class="course-hero photo-slide info-hero"><span>전국 골프장 정보</span><small>${course.region} ${course.city} · ${holeLabel(course)}</small></div>
  <section class="course-overview"><b>${course.name}</b><span class="info-badge">ALL:GOLF 예약 미지원</span><span>📍 ${course.address||`${course.region} ${course.city} · 상세 주소 확인 필요`} · ${holeLabel(course)} · ${typeLabel(course)}</span><p>현재는 골프장 정보만 제공합니다. 확인되지 않은 가격이나 티타임은 표시하지 않습니다.</p><div class="detail-links"><button data-map>지도보기</button><button data-share>공유하기</button></div></section>
  <section class="course-info-card" id="course-info"><h2>골프장 정보</h2><dl><div><dt>주소</dt><dd>${course.address||'확인 필요'}</dd></div><div><dt>운영형태</dt><dd>${typeLabel(course)}</dd></div><div><dt>총 홀 수</dt><dd>${holeLabel(course)}</dd></div><div><dt>코스명</dt><dd>${courseNames}</dd></div><div><dt>대표 전화</dt><dd>${course.phone||'확인 필요'}</dd></div><div><dt>예약 지원</dt><dd>현재 ALL:GOLF 예약 미지원</dd></div></dl>${course.officialWebsite?`<a class="official-link" href="${course.officialWebsite}" target="_blank" rel="noopener noreferrer">공식 홈페이지</a>`:''}</section>
  <section class="course-info-card"><h2>정보 출처</h2><p>${course.sourceName||'공개 자료'}</p><p>자료 기준일 ${course.sourceAsOf||course.lastVerified||'확인 필요'}</p>${course.source?`<a class="official-link" href="${course.source}" target="_blank" rel="noopener noreferrer">출처 확인</a>`:''}<small class="source-disclaimer">출처 기준일 이후 운영 정보가 변경되었을 수 있습니다. 방문 전 골프장 공식 채널에서 확인해주세요.</small></section>
  <section class="info-box"><h3>예약 안내</h3><p>이 골프장은 전국 정보 검색 대상이며 ALL:GOLF의 실제 또는 시연 예약 재고가 연결되어 있지 않습니다.</p></section>`;
  return `<div class="detail-top"><button class="back" data-go="list">\u2039</button><div class="detail-course-title"><h1>${course.name}</h1><button class="heart compact-favorite ${saved?'saved':''}" data-favorite="${course.id}" aria-label="\ucc1c\ud558\uae30">${saved?'\u2665':'\u2661'}</button></div><div class="detail-actions"><button data-share aria-label="\uacf5\uc720\ud558\uae30">\u21a7</button></div></div>
  <div class="course-hero photo-slide"><span>시연용 예약 화면</span><small>${course.region} ${course.area} · ${holeLabel(course)}</small></div>
  <section class="course-overview"><b>${course.name}</b><span>${demoNotice}</span><span>📍 ${course.address||`${course.region} ${course.city} · 상세 주소 확인 필요`} · ${holeLabel(course)} · ${typeLabel(course)}</span><p>${course.description||'골프장 소개 확인 필요'}</p><div class="detail-links"><button data-map>지도보기</button><button data-share>공유하기</button></div></section>
  <div class="detail-tabs"><button class="active" data-scroll="tee-times">\uc608\uc57d</button><button data-scroll="course-info">\uace8\ud504\uc7a5\uc815\ubcf4</button><button data-scroll="course-layout">\ucf54\uc2a4</button><button data-scroll="fee-info">\uc774\uc6a9\uc694\uae08</button></div>
  <section class="course-info-card" id="course-info"><h2>골프장 정보</h2><dl><div><dt>주소</dt><dd>${course.address||'확인 필요'}</dd></div><div><dt>운영형태</dt><dd>${typeLabel(course)}</dd></div><div><dt>총 홀 수</dt><dd>${holeLabel(course)}</dd></div><div><dt>코스명</dt><dd>${courseNames}</dd></div></dl>${course.officialWebsite?`<a class="official-link" href="${course.officialWebsite}" target="_blank" rel="noopener noreferrer">공식 홈페이지</a>`:''}</section>
  <section class="course-info-card" id="course-layout"><h2>코스 정보</h2><p>${courseNames}</p></section>
  <section class="course-info-card" id="fee-info"><h2>이용요금</h2><dl><div><dt>실제 그린피</dt><dd>${actualGreen}</dd></div><div><dt>시연 그린피</dt><dd>${won(course.demoGreenFee)} / 1인<small>시연 가격 · 실제 판매가 아님</small></dd></div><div><dt>카트비</dt><dd>${course.cartFee==null?'가격 확인 필요':won(course.cartFee)}</dd></div><div><dt>캐디피</dt><dd>${course.caddieFee==null?'가격 확인 필요':won(course.caddieFee)}</dd></div></dl></section>
  <div id="tee-times" class="tee-date-head"><h2 class="tee-title">\uc608\uc57d \ub0a0\uc9dc</h2><button type="button" class="calendar-button" data-sheet aria-label="\ub2ec\ub825\uc5d0\uc11c \ub0a0\uc9dc \uc120\ud0dd">\ud83d\udcc5</button></div><div class="date-row">${dateOptions().map(item=>{const [m,day,weekday]=item.label.match(/(\d+)\uc6d4 (\d+)\uc77c \((.)\)/).slice(1);return `<button type="button" class="date ${date===item.label?'active':''}" data-date="${item.label}" data-iso="${item.iso}">${m}/${day}<strong>${weekday}</strong></button>`}).join('')}</div>
  <div class="chips"><button class="chip active">\uc804\uccb4</button><button class="chip">1\ubd80</button><button class="chip">2\ubd80</button><button class="chip">3\ubd80</button></div>
  <h2 class="tee-title">시연용 티타임</h2><div class="time-list">${displayTimes.map(t=>`<div class="time ${t.closed?'closed-time':''}"><span><b>${t.time}</b>${t.specialOffer?`<em class="special-badge">특가 ${t.specialOffer.discountRate}%</em>`:''}<br><small>${t.specialOffer?`<s>${won(t.regularPrice)}</s> <strong class="deal-price">${won(t.price)}</strong>`:won(t.price)} / 1인 · ${t.closed?'예약 마감':`잔여 ${t.remaining}팀`} · 시연용</small></span><button class="time-reserve ${t.closed?'disabled':''}" data-tee-id="${t.id}" ${t.closed?'disabled':''}>${t.closed?'마감':'예약'}</button></div>`).join('')}</div>
  <section class="info-box"><h3>이용 안내</h3><div><span>실제 취소 규정</span><b>${course.cancellationPolicy||'골프장 확인 필요'}</b></div><p class="demo-warning">${demoNotice} 티타임·가격·잔여팀은 기능 확인을 위한 가상 데이터입니다.</p></section>
  <div class="detail-booking-dock"><span>시연 최저가<small>실제 판매가 아님</small><b>${won(Math.min(...displayTimes.map(t=>t.price)))}~</b></span><button data-scroll="tee-times">티타임 보기</button></div>`;
}

function booking(){
  if(!tee) return `<div class="empty">\ud2f0\ud0c0\uc784\uc744 \uba3c\uc800 \uc120\ud0dd\ud574\uc8fc\uc138\uc694.</div>`;
  tee=timesFor(course).find(item=>item.id===tee.id)||tee;
  const p=paymentFor(course,tee,people);
  const companionFields=Array.from({length:Math.max(0,people-1)},(_,index)=>`<label>동반자 ${index+1} 이름 (선택)<input class="field companion-name" data-companion-index="${index}" value="${esc(bookingDraft.companions[index]||'')}" placeholder="동반자 이름"></label>`).join('');
  return `<div class="detail-top"><button class="back" data-go="detail">‹</button><h1>예약/결제 확인</h1></div><p class="notice"><b>${demoNotice}</b><br>실제 카드 결제나 금융정보 입력은 발생하지 않습니다.</p><article class="reservation"><h3>${course.name}</h3><p>${date}<br><b>${tee.time}</b> · ⛳ ${holeLabel(course)}</p><label class="booking-people-label">예약 인원 <select id="booking-people"><option value="2" ${people===2?'selected':''}>2명</option><option value="3" ${people===3?'selected':''}>3명</option><option value="4" ${people===4?'selected':''}>4명</option></select></label></article>
  <section class="payment-box">${tee.specialOffer?`<div><span>정상 그린피</span><b><s>${won(p.regularGreenFee)}</s> / 1인</b></div><div class="deal-payment"><span>특가 할인</span><b>-${won(p.discountTotal)} (${tee.specialOffer.discountRate}%)</b></div><div><span>할인 적용 그린피</span><b>${won(p.appliedGreenFee)} × ${people}명 = ${won(p.greenTotal)}</b></div>`:`<div><span>그린피</span><b>${won(p.appliedGreenFee)} × ${people}명 = ${won(p.greenTotal)}</b></div>`}${p.playerSurcharge?`<div class="player-surcharge"><span>${people}인 플레이 추가금</span><b>${won(p.playerSurcharge)} / 1인 포함</b></div>`:''}<div><span>카트비</span><b>${won(p.cart)} / 팀</b></div><div><span>캐디피</span><b>${won(p.caddie)} / 팀</b></div><hr><div><span>총 예상 이용금액</span><b>${won(p.totalEstimated)}</b></div><div class="mint"><span>온라인 예약금</span><b>${won(p.paidDeposit)}</b></div><div><span>현장 결제 예정금액</span><b>${won(p.onsite)}</b></div><p>평일·주말 및 예약 인원 정책을 반영한 시연 금액입니다. 실제 판매·결제가 아닙니다.</p></section>
  <section class="form-section"><label>\uc608\uc57d\uc790 \uc774\ub984<input class="field required" id="booker" value="${esc(bookingDraft.booker)}" placeholder="\uc774\ub984\uc744 \uc785\ub825\ud558\uc138\uc694"></label><label>\ud734\ub300\uc804\ud654\ubc88\ud638<input class="field required" id="phone" value="${esc(bookingDraft.phone)}" placeholder="010-0000-0000"></label><div class="companion-section"><h3>동반자 정보 <small>${people-1}명 · 선택 입력</small></h3>${companionFields}</div><label>\uc694\uccad\uc0ac\ud56d (\uc120\ud0dd)<input class="field" id="request" value="${esc(bookingDraft.request)}" placeholder="\uc694\uccad\uc0ac\ud56d\uc744 \uc785\ub825\ud558\uc138\uc694"></label></section><label class="agree"><input type="checkbox" id="terms" ${bookingDraft.terms?'checked':''}> \uc608\uc57d \ubc0f \ucde8\uc18c \uaddc\uc815\uc5d0 \ub3d9\uc758\ud569\ub2c8\ub2e4.</label><label class="agree"><input type="checkbox" id="refund" ${bookingDraft.refund?'checked':''}> 시연용 취소/환불 정책에 동의합니다.</label><div class="booking-bar"><button class="primary disabled" id="pay" disabled>시연 결제하기</button></div>`;
}

function complete(){
  const id=localStorage.getItem('allGolfLastReservation');const r=getReservations().find(item=>item.id===id);
  if(!r) return `<div class="empty">\ucd5c\uadfc \uc608\uc57d \ub0b4\uc5ed\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.<br><button class="primary small-primary" data-go="home">\ud648\uc73c\ub85c</button></div>`;
  return `<section class="complete"><div class="complete-check">✓</div><div class="kicker">시연용 예약</div><h1>시연용 예약이 완료되었습니다.</h1><p>${r.courseName}<br>${r.date} · ${r.time}<br><b>${r.people}명 플레이</b> · ${r.holes?`${r.holes}홀`:'홀 수 확인 필요'}</p>${r.companions?.length?`<div class="complete-companions"><span>동반자</span><b>${r.companions.join(' · ')}</b></div>`:''}<article class="confirm-number"><span>시연 예약번호</span><b>${r.number}</b></article><p class="muted">${demoNotice}<br>실제 골프장에 예약이 접수되거나 알림톡이 발송되지는 않습니다.</p><button class="primary" data-go="my">내 예약 확인</button><button class="home-button" data-go="home">홈으로</button></section>`;
}
function my(){
  const all=getReservations(); const items=all.filter(r=>myTab==='upcoming'?['confirmed','upcoming'].includes(r.status):myTab==='past'?['completed','no_show'].includes(r.status):['cancelled','cancel_requested'].includes(r.status));
  return `<div class="my-top"><h1>\ub0b4 \uc608\uc57d</h1><p>\uc608\uc57d \ub0b4\uc5ed\uc744 \ud55c\ub208\uc5d0 \ud655\uc778\ud558\uc138\uc694.</p></div><button class="favorite-entry" data-go="favorites"><span>\u2665</span><div><b>\ucc1c\ud55c \uace8\ud504\uc7a5</b><small>\ud604\uc7ac ${favorites().length}\uacf3\uc744 \ucc1c\ud588\uc5b4\uc694</small></div><i>\u203a</i></button><div class="tabs"><button class="${myTab==='upcoming'?'active':''}" data-mytab="upcoming">\ub2e4\uac00\uc624\ub294 \uc608\uc57d</button><button class="${myTab==='past'?'active':''}" data-mytab="past">\uc9c0\ub09c \uc608\uc57d</button><button class="${myTab==='cancelled'?'active':''}" data-mytab="cancelled">\ucde8\uc18c\ub41c \uc608\uc57d</button></div><div class="reservation-list">${items.map(resCard).join('')||'<div class="empty">\ud574\ub2f9 \uc608\uc57d \ub0b4\uc5ed\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.</div>'}</div>`;
}
function resCard(r){const isCancelled=['cancelled','cancel_requested'].includes(r.status);return `<article class="reservation-card"><span class="status ${isCancelled?'cancelled':''}">${r.demo?'시연용 · ':''}${isCancelled?'취소 완료':'예약 완료'}</span><h3>${r.courseName||r.course}</h3><p>${r.date} · ${r.time} · <b>${r.people}명 플레이</b></p>${r.companions?.length?`<p class="companion-summary">동반자 ${r.companions.join(' · ')}</p>`:''}<div><span>예약번호 ${r.number}</span><b>시연용 예약금 ${won(r.paidDeposit??r.online??r.deposit)}</b>${isCancelled?`<span>시연 환불 ${won(r.refundAmount||0)} · ${r.refundStatus==='demo_refunded'?'시연 환불 완료':'처리 확인 필요'}</span>`:''}</div>${!isCancelled?`<button class="secondary" data-cancel="${r.number||r.id}">예약 취소</button>`:''}</article>`}
function favoritesPage(){const saved=favorites().map(id=>courses.find(c=>c.id===id)).filter(Boolean);return `<div class="result-top"><button class="back" data-go="my">\u2039</button><h1>\ucc1c\ud55c \uace8\ud504\uc7a5</h1></div><p class="page-desc">\uad00\uc2ec \uace8\ud504\uc7a5\uc758 \uc608\uc57d \uac00\ub2a5 \ud2f0\ud0c0\uc784\uc744 \ud55c\ub208\uc5d0 \ud655\uc778\ud558\uc138\uc694.</p><div class="favorite-list">${saved.map(favoriteCard).join('')||'<div class="empty">\uc544\uc9c1 \ucc1c\ud55c \uace8\ud504\uc7a5\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.<br><button class="primary small-primary" data-go="list">\uace8\ud504\uc7a5 \ucc3e\uae30</button></div>'}</div>`}
function favoriteCard(c){const first=timesFor(c)[0];return `<article class="favorite-card"><div class="favorite-card-head"><div><h3>${c.name}</h3><p>${c.region} · ${c.city} · ${holeLabel(c)}</p></div><button class="heart saved" data-favorite="${c.id}" aria-label="찜 해제">♥</button></div>${c.demo&&first?`<div class="favorite-info"><b>${won(first.price)} / 1인부터 · 시연용</b><span>시연 티타임 ${first.time}부터</span><span>실제 판매 티타임 아님</span></div>`:`<div class="favorite-info none"><b>현재 ALL:GOLF 예약 미지원</b><span>공식 골프장 정보만 제공됩니다.</span></div>`}<button class="favorite-detail" data-course="${c.id}">상세보기</button></article>`}
function simplePage(title,text){return `<div class="empty"><h1>${title}</h1><p>${text}</p><button class="primary" data-go="home">\ud648\uc73c\ub85c</button></div>`}

function renderSheetDates(){const holder=document.querySelector('#sheet-date');holder.innerHTML=dateOptions().map(({iso,label})=>`<button type="button" class="${iso===calendarDate?'selected':''}" data-date="${iso}">${label.replace(/^\d{4}년 /,'')}</button>`).join('');holder.querySelectorAll('button').forEach(btn=>btn.onclick=()=>{holder.querySelectorAll('button').forEach(item=>item.classList.remove('selected'));btn.classList.add('selected');document.querySelector('#calendar-date').value=btn.dataset.date})}
function openSheet(){sheetRegion.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b.dataset.region===region));document.querySelectorAll('#sheet-people button').forEach(button=>button.classList.toggle('selected',Number(button.textContent.match(/\d+/)?.[0])===people));updateSheetCities(region);sheetCity.value=city;document.querySelector('#calendar-date').value=calendarDate;renderSheetDates();document.querySelector('#sheet').classList.add('open')}
function closeSheet(){document.querySelector('#sheet').classList.remove('open')}
function modal(html=''){const layer=document.querySelector('#modal');layer.innerHTML=html?`<div class="modal-backdrop"></div><div class="modal-box">${html}</div>`:'';if(html){layer.querySelector('.modal-backdrop').onclick=()=>modal();layer.querySelector('#close-modal')?.addEventListener('click',()=>modal())}}
function captureBookingDraft(){bookingDraft={booker:document.querySelector('#booker')?.value.trim()||bookingDraft.booker,phone:document.querySelector('#phone')?.value.trim()||bookingDraft.phone,request:document.querySelector('#request')?.value.trim()||bookingDraft.request,companions:[...document.querySelectorAll('.companion-name')].map(input=>input.value.trim()),terms:document.querySelector('#terms')?.checked??bookingDraft.terms,refund:document.querySelector('#refund')?.checked??bookingDraft.refund}}
function releaseActiveHold(){if(activeHold&&shared?.releaseTeeHold)shared.releaseTeeHold(activeHold.id,bookingSessionId);activeHold=null}
function reserve(){
  captureBookingDraft();const name=bookingDraft.booker,phone=bookingDraft.phone,request=bookingDraft.request,companions=bookingDraft.companions.filter(Boolean);
  tee=timesFor(course).find(item=>item.id===tee.id)||tee;
  const p=paymentFor(course,tee,people);
  const holdResult=shared?.acquireTeeHold?shared.acquireTeeHold(course.id,calendarDate,tee.id,bookingSessionId):{ok:true,hold:null};
  if(!holdResult.ok){modal(`<h2>잠시 예약할 수 없습니다</h2><p>${holdResult.reason==='held_by_other'?'다른 사용자가 이 티타임의 결제를 진행 중입니다. 잠시 후 다시 시도해주세요.':'방금 마감된 티타임입니다. 다른 시간을 선택해주세요.'}</p><button class="primary" id="close-modal">확인</button>`);return}
  activeHold=holdResult.hold;
  const closePayment=()=>{releaseActiveHold();modal()};
  modal(`<h2>시연 결제 확인</h2><p>${course.name}<br>${date} ${tee.time} · <b>${people}명</b><br><b>${demoNotice}</b></p><div class="hold-notice"><b>티타임 임시 확보</b><span>중복 예약 방지를 위해 5분 동안 이 티타임을 확보했습니다.</span></div><strong>온라인 예약금 ${won(p.paidDeposit)}</strong><div class="modal-actions"><button class="home-button" id="close-modal">돌아가기</button><button class="primary" id="confirm-reserve">시연 결제 완료</button></div>`);
  document.querySelector('#close-modal').onclick=closePayment;document.querySelector('.modal-backdrop').onclick=closePayment;document.querySelector('#confirm-reserve').onclick=e=>{if(e.target.disabled)return;e.target.disabled=true;e.target.textContent='처리 중...';setTimeout(()=>{const selectedTeeId=tee.id,latestTee=timesFor(course).find(item=>item.id===selectedTeeId);if(!latestTee||latestTee.closed||latestTee.remaining<1){releaseActiveHold();modal('<h2>예약 불가</h2><p>방금 마감된 티타임입니다. 다른 시간을 선택해주세요.</p><button class="primary" id="close-modal">확인</button>');return}const selectedTee={...latestTee},special=selectedTee.specialOffer?{...selectedTee.specialOffer}:null,latestPayment=paymentFor(course,selectedTee,people),policySnapshot={...ratesFor(course).cancellationPolicy};const committed=activeHold&&shared?.commitTeeHold?shared.commitTeeHold(activeHold.id,bookingSessionId):{ok:!shared||shared.reserveTee(course.id,calendarDate,selectedTee.time)};activeHold=null;if(!committed.ok){modal('<h2>예약 불가</h2><p>임시 확보 시간이 끝났거나 다른 예약이 먼저 완료되었습니다. 다시 선택해주세요.</p><button class="primary" id="close-modal">확인</button>');return}const serial=String(Date.now()).slice(-5);const ymd=calendarDate.replaceAll('-','').slice(2);const item={id:`r-${Date.now()}`,number:`AG-${ymd}-${serial}`,courseId:course.id,courseName:course.name,date,dateISO:calendarDate,time:selectedTee.time,teeTimeId:selectedTee.id||`${course.id}::${calendarDate}::${selectedTee.time}`,people,companions,holes:course.holes,booker:name,phone,request,baseGreenFee:latestPayment.baseAppliedGreenFee,playerSurcharge:latestPayment.playerSurcharge,regularGreenFee:latestPayment.regularGreenFee,appliedGreenFee:latestPayment.appliedGreenFee,discountAmount:latestPayment.discountTotal,greenFee:latestPayment.appliedGreenFee,greenTotal:latestPayment.greenTotal,cart:latestPayment.cart,caddie:latestPayment.caddie,totalEstimated:latestPayment.totalEstimated,paidDeposit:latestPayment.paidDeposit,online:latestPayment.paidDeposit,onsite:latestPayment.onsite,pricingSnapshot:{dateType:[0,6].includes(new Date(`${calendarDate}T00:00:00`).getDay())?'weekend':'weekday',people,playerSurcharge:latestPayment.playerSurcharge},specialOfferId:special?.id||null,specialOfferName:special?.name||null,specialOfferSnapshot:special?{id:special.id,name:special.name,regularPrice:special.regularPrice,specialPrice:special.specialPrice,discountRate:special.discountRate,roundDate:special.roundDate,time:special.time}:null,cancellationPolicySnapshot:policySnapshot,paymentStatus:'demo_paid',status:'confirmed',demo:true,createdAt:new Date().toISOString()};setReservations([item,...getReservations()]);localStorage.setItem('allGolfLastReservation',item.id);bookingDraft={booker:'',phone:'',request:'',companions:[]};modal();go('complete')},350)};
}
function toggleFavorite(id){const now=favorites();const next=now.includes(id)?now.filter(x=>x!==id):[...now,id];localStorage.setItem('allGolfFavorites',JSON.stringify([...new Set(next)]));render()}
function cancelReservation(reference){const target=getReservations().find(r=>r.number===reference||r.id===reference);if(!target)return;const refund=shared?.calculateCancellation?shared.calculateCancellation(target):{paidDeposit:Number(target.paidDeposit??target.online??target.deposit??0),cancellationFee:0,refundAmount:Number(target.paidDeposit??target.online??target.deposit??0)};modal(`<h2>예약 취소 확인</h2><div class="cancel-summary"><p><b>${target.number}</b><br>${target.courseName||target.course}<br>${target.dateISO||target.date} · ${target.time}</p><div><span>결제한 예약금</span><b>${won(refund.paidDeposit)}</b></div><div><span>예상 취소수수료</span><b>${won(refund.cancellationFee)}</b></div><div><span>예상 시연 환불금액</span><b>${won(refund.refundAmount)}</b></div><small>시연용 취소/환불 정책에 따른 계산이며 실제 환불이 아닙니다.</small></div><div class="modal-actions"><button class="home-button" id="close-modal">취소하지 않기</button><button class="primary" id="confirm-cancel">예약 취소하기</button></div>`);document.querySelector('#close-modal').onclick=()=>modal();document.querySelector('#confirm-cancel').onclick=()=>{if(shared?.cancelReservation){shared.cancelReservation(reference,'사용자 취소')}else{const items=getReservations();setReservations(items.map(r=>(r.number===reference||r.id===reference)?{...r,status:'cancelled',cancelledAt:new Date().toISOString(),cancelReason:'사용자 취소',paidDeposit:refund.paidDeposit,cancellationFee:refund.cancellationFee,refundAmount:refund.refundAmount,refundStatus:'demo_refunded'}:r))}myTab='cancelled';modal();go('my')}}

function bind(){
  document.querySelectorAll('.bottom-nav [data-go], .brand[data-go]').forEach(el=>el.onclick=()=>go(el.dataset.go));
  root.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>go(el.dataset.go));
  root.querySelectorAll('[data-course]').forEach(el=>el.onclick=e=>{e.stopPropagation();course=courses.find(c=>c.id===el.dataset.course)||course;go('detail')});
  root.querySelectorAll('[data-reserve-course]').forEach(el=>el.onclick=e=>{e.stopPropagation();const selected=courses.find(c=>c.id===el.dataset.reserveCourse);if(!selected?.bookable)return;course=selected;go('detail');requestAnimationFrame(()=>document.querySelector('#tee-times')?.scrollIntoView({behavior:'smooth'}))});
  root.querySelectorAll('[data-tee-id]').forEach(el=>el.onclick=()=>{tee=timesFor(course).find(t=>t.id===el.dataset.teeId);if(!tee||tee.closed)return;go('booking')});
  root.querySelectorAll('[data-special-course]').forEach(el=>el.onclick=()=>{const c=courses.find(item=>item.id===el.dataset.specialCourse);if(!c)return;course=c;calendarDate=el.dataset.specialDate;date=formatCalendarDate(calendarDate);tee=timesFor(course,calendarDate).find(item=>item.id===el.dataset.specialTee)||null;if(!tee||tee.closed)return;go('booking')});
  const bookingPeople=root.querySelector('#booking-people');if(bookingPeople)bookingPeople.onchange=()=>{captureBookingDraft();people=Number(bookingPeople.value);render()};
  root.querySelectorAll('[data-date]').forEach(el=>el.onclick=event=>{event.preventDefault();event.stopPropagation();date=el.dataset.date;calendarDate=el.dataset.iso||calendarDate;tee=null;const scrollY=window.scrollY;render();requestAnimationFrame(()=>window.scrollTo({top:scrollY}))});
  root.querySelectorAll('[data-sheet]').forEach(el=>el.onclick=openSheet);
  root.querySelectorAll('[data-sort]').forEach(el=>el.onclick=()=>{sort=el.dataset.sort;render()});
  root.querySelectorAll('[data-region-filter]').forEach(el=>el.onclick=()=>{region=el.dataset.regionFilter;city='';visibleCount=30;render()});
  const cityFilter=root.querySelector('#result-city');if(cityFilter)cityFilter.onchange=()=>{city=cityFilter.value;render()};
  const operationSelect=root.querySelector('#operation-filter');if(operationSelect)operationSelect.onchange=()=>{operationFilter=operationSelect.value;render()};
  const holesSelect=root.querySelector('#holes-filter');if(holesSelect)holesSelect.onchange=()=>{holesFilter=holesSelect.value;visibleCount=30;render()};
  const availabilitySelect=root.querySelector('#availability-filter');if(availabilitySelect)availabilitySelect.onchange=()=>{availabilityFilter=availabilitySelect.value;visibleCount=30;render()};
  root.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filters=filters.includes(el.dataset.filter)?filters.filter(x=>x!==el.dataset.filter):[...filters,el.dataset.filter];render()});
  root.querySelectorAll('[data-reset-search]').forEach(el=>el.onclick=()=>{sort='recommend';filters=[];query='';region='전체';city='';operationFilter='all';holesFilter='all';availabilityFilter='all';visibleCount=30;render()});
  root.querySelectorAll('[data-load-more]').forEach(el=>el.onclick=()=>{visibleCount+=30;render()});
  root.querySelectorAll('[data-scroll]').forEach(el=>el.onclick=()=>document.querySelector(`#${el.dataset.scroll}`)?.scrollIntoView({behavior:'smooth',block:'start'}));
  root.querySelectorAll('[data-favorite]').forEach(el=>el.onclick=e=>{e.stopPropagation();toggleFavorite(el.dataset.favorite)});
  root.querySelectorAll('[data-mytab]').forEach(el=>el.onclick=()=>{myTab=el.dataset.mytab;render()});
  root.querySelectorAll('[data-cancel]').forEach(el=>el.onclick=()=>cancelReservation(el.dataset.cancel));
  root.querySelectorAll('[data-share]').forEach(el=>el.onclick=()=>modal(`<h2>\uacf5\uc720\ud558\uae30</h2><p>\ud604\uc7ac\ub294 \uc2dc\uc5f0\uc6a9 \uae30\ub2a5\uc785\ub2c8\ub2e4.</p><button class="primary" id="close-modal">\ud655\uc778</button>`));
  root.querySelectorAll('[data-map]').forEach(el=>el.onclick=()=>modal(`<h2>\uc9c0\ub3c4\ubcf4\uae30</h2><p>${course.address}</p><button class="primary" id="close-modal">\ud655\uc778</button>`));
  root.querySelectorAll('[data-alert]').forEach(el=>el.onclick=()=>modal(`<h2>\ucde8\uc18c\ud2f0 \uc54c\ub9bc</h2><p>\uc608\uc57d \ud50c\ub85c\uc6b0 \uc644\ub8cc \ud6c4 \uc21c\ucc28\uc801\uc73c\ub85c \uc81c\uacf5\ud560 \uae30\ub2a5\uc785\ub2c8\ub2e4.</p><button class="primary" id="close-modal">\ud655\uc778</button>`));
  root.querySelectorAll('[data-benefit]').forEach(el=>el.onclick=()=>modal(`<h2>\ud61c\ud0dd \uc548\ub0b4</h2><p>\ud604\uc7ac\ub294 \uc2dc\uc5f0\uc6a9 \ud61c\ud0dd \ub370\uc774\ud130\uc785\ub2c8\ub2e4. \uc2e4\uc81c \uc11c\ube44\uc2a4\uc5d0\uc11c\ub294 \ud68c\uc6d0 \ub4f1\uae09\uacfc \uc0ac\uc6a9 \uc870\uac74\uc5d0 \ub530\ub77c \uc801\uc6a9\ub429\ub2c8\ub2e4.</p><button class="primary" id="close-modal">\ud655\uc778</button>`));
  const form=root.querySelector('#search-form');if(form)form.addEventListener('submit',event=>{event.preventDefault();query=root.querySelector('#home-query').value.trim();operationFilter='all';holesFilter='all';availabilityFilter='all';filters=[];sort='recommend';visibleCount=30;page='list';render();window.scrollTo({top:0})});
  root.querySelectorAll('[data-quick]').forEach(el=>el.onclick=()=>{const v=el.dataset.quick;if(v==='2\uc778 \uac00\ub2a5'||v==='\ud2b9\uac00')filters=filters.includes(v)?filters.filter(x=>x!==v):[...filters,v];if(v==='오늘')calendarDate=todayISO;if(v==='내일')calendarDate=shiftISO(todayISO,1);if(v==='주말')calendarDate=nextWeekendISO();dateAnchor=calendarDate;date=formatCalendarDate(calendarDate);go('list')});
  const pay=root.querySelector('#pay');if(pay){const update=()=>{const ok=root.querySelector('#booker').value.trim()&&root.querySelector('#phone').value.trim()&&root.querySelector('#terms').checked&&root.querySelector('#refund').checked;pay.disabled=!ok;pay.classList.toggle('disabled',!ok)};root.querySelectorAll('.required,#terms,#refund').forEach(el=>el.addEventListener('input',update));root.querySelectorAll('#terms,#refund').forEach(el=>el.addEventListener('change',update));pay.onclick=reserve;update()}
  document.querySelectorAll('#modal #close-modal').forEach(el=>el.onclick=()=>modal());
}
function render(){
  const content=page==='home'?home():page==='benefits'?benefits():page==='favorites'?favoritesPage():page==='list'?list():page==='detail'?detail():page==='booking'?booking():page==='complete'?complete():page==='my'?my():page==='join'?simplePage('\uc870\uc778','\uc608\uc57d \ud50c\ub85c\uc6b0 \uc644\uc131 \ud6c4 \uc21c\ucc28\uc801\uc73c\ub85c \uc81c\uacf5\ud569\ub2c8\ub2e4.'):page==='lesson'?simplePage('\uace8\ud504\ub808\uc2a8','\uc774\ud6c4 \ucd94\uac00\ub420 \uc608정\uc785\ub2c8\ub2e4.'):simplePage('\uace8\ud504\uc5ec\ud589','\uc774\ud6c4 \ucd94\uac00\ub420 \uc608정\uc785\ub2c8\ub2e4.');
  root.innerHTML=content;document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.go===page));bind();
}

document.querySelector('#sheet-close').onclick=closeSheet;
document.querySelector('#sheet').onclick=e=>{if(e.target.id==='sheet')closeSheet()};
document.querySelector('#calendar-date').value=todayISO;
const sheetRegion=document.querySelector('#sheet-region'),sheetCity=document.querySelector('#sheet-city');
function updateSheetCities(selected){const previous=sheetCity.value;sheetCity.innerHTML='<option value="">전체 시·군</option>'+citiesFor(selected).map(value=>`<option value="${value}">${value}</option>`).join('');if(citiesFor(selected).includes(previous))sheetCity.value=previous}
sheetRegion.innerHTML=regionOptions.map(item=>`<button class="${item.code==='전체'?'selected':''}" data-region="${item.code}">${item.label}</button>`).join('');
sheetRegion.querySelectorAll('button').forEach(btn=>btn.onclick=()=>{sheetRegion.querySelectorAll('button').forEach(b=>b.classList.remove('selected'));btn.classList.add('selected');updateSheetCities(btn.dataset.region)});
updateSheetCities('전체');
document.querySelectorAll('#sheet-people button').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('#sheet-people button').forEach(b=>b.classList.remove('selected'));btn.classList.add('selected')});
document.querySelector('#sheet-search').onclick=()=>{const r=document.querySelector('#sheet-region .selected');region=r?.dataset.region||'전체';city=sheetCity.value;const direct=document.querySelector('#calendar-date')?.value;if(direct){calendarDate=direct;dateAnchor=direct;date=formatCalendarDate(direct)}const p=document.querySelector('#sheet-people .selected');people=Number((p?.textContent||'4').match(/\d+/)?.[0]||4);closeSheet();page='list';render();window.scrollTo({top:0})};
window.addEventListener('storage',event=>{if(event.key===shared?.OPS_KEY||event.key===shared?.RESERVATION_KEY)render()});
window.addEventListener('allgolf:datachange',render);
render();
